@st.cache_data(show_spinner=False)
def load_df(path: str, sig: str) -> pd.DataFrame:
    df = fetch_all().fillna("")
    for c in FIELDS:
        if c not in df.columns:
            df[c] = ""
        df[c] = df[c].astype(str).str.strip()
    df["Tahun Terbit"] = df["Tahun Terbit"].str.extract(r"(\d{4})", expand=False).fillna("")
    df = df.drop_duplicates(subset=["No. SK", "No. TBN", "Badan Hukum"]).reset_index(drop=True)
    df["chunk"] = (
        "Badan Hukum: " + df["Badan Hukum"] + " | Jenis Badan Hukum: " + df["Jenis Badan Hukum"]
        + " | Jenis Transaksi: " + df["Jenis Transaksi"] + " | Kedudukan: " + df["Kedudukan"]
        + " | Notaris: " + df["Notaris"] + " | No. SK: " + df["No. SK"] + " | Tanggal SK: " + df["Tanggal SK"]
        + " | No. Akta: " + df["No Akta"] + " | Tanggal Akta: " + df["Tanggal Akta"]
        + " | No. BN: " + df["No BN"] + " | No. TBN: " + df["No. TBN"] + " | Tahun Terbit: " + df["Tahun Terbit"]
    )
    return df


def file_sig(path: str) -> str:
    # penanda isi tabel Supabase (jumlah baris + id terakhir); berubah bila data ditambah
    return db_signature()


STOP = {"pt", "cv", "yayasan", "ud", "tbk", "persero", "perseroan", "terbatas", "dan", "di", "oleh", "sh",
        "mkn", "kn", "notaris", "dr", "hj", "ny", "tn", "sp", "the", "of"}


def toks(s: str):
    return [t for t in re.findall(r"[a-z0-9]+", str(s).lower()) if t not in STOP and len(t) > 1]


@st.cache_resource(show_spinner=False)
def load_embedder(name: str):
    from sentence_transformers import SentenceTransformer
    return SentenceTransformer(name)


@st.cache_resource(show_spinner=False)
def build_index(path: str, sig: str, use_dense: bool, dense_name: str):
    df = load_df(path, sig)
    vec = TfidfVectorizer(analyzer="char_wb", ngram_range=(2, 4), sublinear_tf=True, min_df=2,
                          max_features=400_000, dtype=np.float32, lowercase=True)
    X = vec.fit_transform(df["chunk"].tolist())

    E, dense_ok = None, False
    if use_dense:
        try:
            cache_f = f"{path}.{hashlib.md5((sig + dense_name).encode()).hexdigest()[:10]}.emb.npy"
            if os.path.exists(cache_f):
                E = np.load(cache_f)
            else:
                model = load_embedder(dense_name)
                texts = ["passage: " + t for t in df["chunk"].tolist()]
                bar = st.progress(0.0, text="Membuat embedding dokumen (sekali saja, lalu disimpan)")
                parts = []
                for i in range(0, len(texts), 256):
                    parts.append(model.encode(texts[i:i + 256], normalize_embeddings=True,
                                              show_progress_bar=False).astype(np.float32))
                    bar.progress(min(1.0, (i + 256) / len(texts)))
                bar.empty()
                E = np.vstack(parts)
                np.save(cache_f, E)
            dense_ok = True
        except Exception as e:  # noqa
            st.warning(f"Embedding semantik tidak aktif: {e}. Pencarian memakai TF-IDF saja.")
            E = None

    return {
        "df": df, "vec": vec, "X": X, "E": E, "dense": dense_ok, "dense_name": dense_name,
        "name_tok": [set(toks(x)) for x in df["Badan Hukum"]],
        "not_tok": [set(toks(x)) for x in df["Notaris"]],
        "kedudukan": sorted({k for k in df["Kedudukan"] if k}, key=len, reverse=True),
        "jenis": sorted({k for k in df["Jenis Transaksi"] if k}),
        "tahun": sorted({k for k in df["Tahun Terbit"] if k}),
    }


# ----------------------------------------------------------------------------
# Filter metadata & pencarian hybrid
# ----------------------------------------------------------------------------
def detect_filters(idx, q: str) -> dict:
    ql = q.lower()
    out = {"tahun": [], "kedudukan": [], "jenis": []}
    out["tahun"] = [y for y in re.findall(r"\b(20\d{2})\b", ql) if y in idx["tahun"]]

    for k in idx["kedudukan"]:
        kl = k.lower()
        base = re.sub(r"^(kota|kabupaten|kab\.?)\s+", "", kl)
        if re.search(r"\b" + re.escape(kl) + r"\b", ql) or (len(base) >= 4 and base != kl and
                                                           re.search(r"\b" + re.escape(base) + r"\b", ql)):
            out["kedudukan"].append(k)
    out["kedudukan"] = [k for k in out["kedudukan"]
                        if not any(k != o and k.lower() in o.lower() for o in out["kedudukan"])] or out["kedudukan"]

    for j in idx["jenis"]:
        if j.lower() in ql:
            out["jenis"].append(j)
    if not out["jenis"]:
        for kw in ("pendirian", "pembubaran", "pemberitahuan", "perubahan"):
            if kw in ql:
                out["jenis"] = [j for j in idx["jenis"] if j.lower().startswith(kw)]
                break
    return out


def effective_filters(idx, q, manual, auto_on):
    """Kembalikan (filter, sumber) - sumber 'manual' atau 'otomatis' per kategori."""
    auto = detect_filters(idx, q) if auto_on else {"tahun": [], "kedudukan": [], "jenis": []}
    flt, src = {}, {}
    for k in ("tahun", "kedudukan", "jenis"):
        if manual.get(k):
            flt[k], src[k] = manual[k], "manual"
        else:
            flt[k], src[k] = auto.get(k, []), "otomatis"
    return flt, src


def cov(a: set, b: set) -> float:
    return len(a & b) / len(a) if a else 0.0


def make_mask(idx, f):
    df = idx["df"]
    m = np.ones(len(df), dtype=bool)
    if f["tahun"]:
        m &= df["Tahun Terbit"].isin(f["tahun"]).values
    if f["kedudukan"]:
        m &= df["Kedudukan"].isin(f["kedudukan"]).values
    if f["jenis"]:
        m &= df["Jenis Transaksi"].isin(f["jenis"]).values
    return m


def search(idx, query, f, k):
    t0 = time.time()
    mask = make_mask(idx, f)
    cand = np.where(mask)[0]
    n_match = int(mask.sum())
    if n_match == 0:
        return [], 0, 0, 0.0, mask
    q = idx["vec"].transform([query.lower()])
    s_lex = (idx["X"][cand] @ q.T).toarray().ravel()
    score = s_lex.copy()
    if idx["E"] is not None:
        qe = load_embedder(idx["dense_name"]).encode(["query: " + query], normalize_embeddings=True)[0]
        s_den = idx["E"][cand] @ qe
        score = 0.5 * s_lex + 0.5 * np.clip((s_den - 0.7) / 0.3, 0, 1)

    qt = set(toks(query))
    top = np.argsort(-score)[:400]          # tahap rerank leksikal (nama badan hukum & notaris)
    for j in top:
        i = cand[j]
        score[j] += 0.5 * cov(idx["name_tok"][i], qt) + 0.25 * cov(idx["not_tok"][i], qt)

    order = np.argsort(-score)[:k]
    hits = []
    for j in order:
        row = idx["df"].iloc[cand[j]].to_dict()
        row["sim"] = float(min(0.99, 1 - np.exp(-2.2 * max(score[j], 0))))
        hits.append(row)
    return hits, n_match, len(top), (time.time() - t0) * 1000, mask


AGG_RE = re.compile(r"\b(rekap|jumlah|berapa|statistik|total|seluruh|semua|banyak)\b", re.I)


def compute_stats(idx, mask):
    sub = idx["df"][mask]
    return {
        "total": int(len(sub)),
        "by_jenis": sub["Jenis Transaksi"].value_counts().head(8).to_dict(),
        "by_kedudukan": sub["Kedudukan"].value_counts().head(5).to_dict(),
        "by_notaris": sub["Notaris"].value_counts().head(5).to_dict(),
    }


def stats_text(s):
    return (f"[STAT] Total entitas sesuai filter: {s['total']}. "
            f"Per jenis transaksi: {json.dumps(s['by_jenis'], ensure_ascii=False)}. "
            f"Kedudukan teratas: {json.dumps(s['by_kedudukan'], ensure_ascii=False)}. "
            f"Notaris teratas: {json.dumps(s['by_notaris'], ensure_ascii=False)}.")


# ----------------------------------------------------------------------------
# LLM (Qwen 3.5) - Ollama / OpenAI-compatible, streaming
# ----------------------------------------------------------------------------
SYSTEM_PROMPT = (
    "Kamu adalah asisten riset hukum untuk data Berita Negara (BN) dan Tambahan Berita Negara (TBN) RI "
    "dari Direktorat Jenderal AHU. Jawab dalam Bahasa Indonesia yang ringkas dan profesional.\n"
    "ATURAN KETAT (Zero-Hallucination):\n"
    "1. Gunakan HANYA informasi di blok KONTEKS. Dilarang menambah fakta dari luar konteks.\n"
    "2. Setiap fakta wajib diberi sitasi nomor sumber, contoh [1] atau [2].\n"
    "3. Salin nomor SK, tanggal, nomor akta, No BN dan No TBN persis seperti di konteks.\n"
    "4. Jika konteks tidak memuat jawabannya, katakan data tidak ditemukan pada indeks.\n"
    "5. Untuk data [STAT], gunakan angka apa adanya tanpa menghitung ulang.\n"
    "Format: satu paragraf pembuka, lalu poin-poin ringkas untuk rincian utama, "
    "lalu (jika relevan) daftar entitas terkait."
)


def build_messages(query, hits, stats):
    ctx = [f"[{i}] {h['chunk']}" for i, h in enumerate(hits, 1)]
    if stats:
        ctx.append(stats_text(stats))
    user = "KONTEKS:\n" + "\n".join(ctx) + f"\n\nPERTANYAAN: {query}\n\nJAWABAN:"
    return [{"role": "system", "content": SYSTEM_PROMPT}, {"role": "user", "content": user}]


def stream_ollama(cfg, messages):
    payload = {"model": cfg["model"], "messages": messages, "stream": True, "think": cfg["think"], "keep_alive": -1,
               "options": {"temperature": cfg["temp"], "num_ctx": 8192}}
    with requests.post(cfg["host"].rstrip("/") + "/api/chat", json=payload, stream=True, timeout=(10, 600)) as r:
        if r.status_code != 200:
            raise RuntimeError(f"Ollama {r.status_code}: {r.text[:300]}")
        for line in r.iter_lines():
            if not line:
                continue
            d = json.loads(line)
            m = d.get("message", {}) or {}
            if m.get("thinking"):
                yield "thinking", m["thinking"]
            if m.get("content"):
                yield "content", m["content"]
            if d.get("done"):
                break


def stream_openai(cfg, messages):
    headers = {"Content-Type": "application/json"}
    if cfg["api_key"]:
        headers["Authorization"] = "Bearer " + cfg["api_key"]
    payload = {"model": cfg["model"], "messages": messages, "stream": True, "temperature": cfg["temp"],
               "chat_template_kwargs": {"enable_thinking": cfg["think"]}}
    with requests.post(cfg["host"].rstrip("/") + "/chat/completions", json=payload, headers=headers,
                       stream=True, timeout=(10, 600)) as r:
        if r.status_code != 200:
            raise RuntimeError(f"API {r.status_code}: {r.text[:300]}")
        for line in r.iter_lines():
            if not line or not line.startswith(b"data:"):
                continue
            data = line[5:].strip()
            if data == b"[DONE]":
                break
            d = json.loads(data)
            delta = (d.get("choices") or [{}])[0].get("delta", {})
            if delta.get("reasoning_content"):
                yield "thinking", delta["reasoning_content"]
            if delta.get("content"):
                yield "content", delta["content"]


def llm_stream(cfg, messages):
    return stream_ollama(cfg, messages) if cfg["provider"] == "Ollama" else stream_openai(cfg, messages)


def _get_retry(url, tries=2, timeout=8, **kw):
    """GET dengan timeout longgar dan satu kali ulang, supaya hambatan sesaat lewat Funnel tidak dianggap server mati."""
    last = None
    for i in range(tries):
        try:
            return requests.get(url, timeout=timeout, **kw)
        except Exception as e:
            last = e
            time.sleep(0.6)
    raise last


def llm_online(cfg) -> bool:
    try:
        if cfg["provider"] == "Ollama":
            r = _get_retry(cfg["host"].rstrip("/") + "/api/tags")
            return r.status_code == 200
        r = _get_retry(cfg["host"].rstrip("/") + "/models",
                       headers={"Authorization": "Bearer " + cfg["api_key"]} if cfg["api_key"] else {})
        return r.status_code == 200
    except Exception:
        return False


def ollama_models(host: str):
    """Daftar model yang terpasang di Ollama. None bila server tidak bisa dihubungi."""
    try:
        r = _get_retry(host.rstrip("/") + "/api/tags")
        r.raise_for_status()
        return [m.get("name", "") for m in r.json().get("models", []) if m.get("name")]
    except Exception:
        return None


def model_installed(name: str, installed) -> bool:
    n = name.strip()
    return bool(installed) and (n in installed or (":" not in n and f"{n}:latest" in installed))


def split_think(raw: str):
    thought = "".join(re.findall(r"<think>(.*?)</think>", raw, flags=re.S))
    clean = re.sub(r"<think>.*?</think>", "", raw, flags=re.S)
    thinking_now = False
    if "<think>" in clean:
        clean, thinking_now = clean.split("<think>")[0], True
    return clean.strip(), thought.strip(), thinking_now


def extractive_answer(hits, stats, query):
    """Cadangan tanpa LLM: jawaban deterministik dari hasil pencarian (tetap 100% terverifikasi)."""
    h = hits[0]
    L = [f"Berdasarkan penelusuran arsip Berita Negara RI, ditemukan **{len(hits)} entitas badan hukum** yang relevan. "
         f"Entitas dengan kecocokan tertinggi adalah **{h['Badan Hukum']}** ({h['Jenis Badan Hukum']}) "
         f"yang berkedudukan di **{h['Kedudukan']}** [1].", ""]
    if stats and AGG_RE.search(query):
        L.append(f"- **Total entitas sesuai filter:** {fmt(stats['total'])}")
        for k, v in list(stats["by_jenis"].items())[:4]:
            L.append(f"- {k}: {fmt(v)}")
        L.append("")
    L += [f"- **Jenis transaksi:** {h['Jenis Transaksi']} (terbit {h['Tahun Terbit']}) [1]",
          f"- **Nomor dan tanggal SK:** `{h['No. SK']}` tertanggal {h['Tanggal SK']} [1]",
          f"- **Akta dan notaris:** Akta No. {h['No Akta']} tanggal {h['Tanggal Akta']} di hadapan Notaris "
          f"**{h['Notaris']}** [1]",
          f"- **Pencatatan Berita Negara:** No. BN {h['No BN']} dan No. TBN **{h['No. TBN']}** [1]"]
    if len(hits) > 1:
        L += ["", "**Entitas terkait lainnya:**"]
        for i, o in enumerate(hits[1:], 2):
            L.append(f"- **{o['Badan Hukum']}**, {o['Jenis Transaksi']} di {o['Kedudukan']}, "
                     f"SK `{o['No. SK']}` [{i}]")
    return "\n".join(L)


def grounding(answer, hits, stats):
    ctx = " ".join(h["chunk"] for h in hits) + (" " + stats_text(stats) if stats else "")
    ctx_digits = ctx.replace(".", "")
    checks = []
    for m in set(re.findall(r"AHU[-.A-Za-z0-9]*[A-Za-z0-9]", answer)):
        checks.append(m in ctx)
    for m in set(re.findall(r"\b\d{2}-\d{2}-\d{4}\b", answer)):
        checks.append(m in ctx)
    for m in set(re.findall(r"\b\d{4,}\b", answer)):
        checks.append(m in ctx or m in ctx_digits)
    cites = re.findall(r"\[(\d+)\]", answer)
    for c in cites:
        checks.append(1 <= int(c) <= len(hits))
    if not checks:
        return 0.6, 0
    return sum(checks) / len(checks), len(set(cites))


def with_cites(text: str, active: int = 0) -> str:
    def rep(m):
        n = int(m.group(1))
        return f'<span class="cite{" on" if n == active else ""}">[{n}]</span>'
    return re.sub(r"\[(\d+)\]", rep, text)


